package com.farmingprofit;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import net.runelite.client.plugins.skillcalculator.skills.HerbloreAction;
import org.junit.Test;
import static org.junit.Assert.*;

/** Test-only independent oracle: shipped RuneLite calculator, not a copy of our rates. */
public class HerbloreCatalogTest
{
    @Test public void everyRecipeMatchesRuneLiteCalculator()
    {
        Map<Integer, Integer> expected = new HashMap<>();
        for (HerbloreAction action : HerbloreAction.values())
        { expected.put(action.getItemId(), Math.round(action.getXp() * 10)); }
        Set<Integer> herbs = new HashSet<>();
        for (HerbloreEstimate.Herb herb : HerbloreEstimate.HERBS)
        {
            assertTrue("Duplicate herb " + herb.name, herbs.add(herb.id));
            Set<Integer> recipes = new HashSet<>();
            for (HerbloreEstimate.Recipe recipe : herb.recipes)
            {
                assertTrue("Duplicate choice " + recipe.name, recipes.add(recipe.id));
                assertEquals("Base XP for " + herb.name + " / " + recipe.name,
                    expected.get(recipe.id), Integer.valueOf(recipe.xpTenths));
            }
        }
    }
    @Test public void everyCleaningRateMatchesRuneLiteCalculator()
    {
        Map<String, HerbloreAction> actions = new HashMap<>();
        for (HerbloreAction action : new HerbloreAction[]{HerbloreAction.GUAM_LEAF, HerbloreAction.MARRENTILL,
            HerbloreAction.TARROMIN, HerbloreAction.HARRALANDER, HerbloreAction.RANARR_WEED,
            HerbloreAction.TOADFLAX, HerbloreAction.IRIT_LEAF, HerbloreAction.AVANTOE, HerbloreAction.KWUARM,
            HerbloreAction.HUASCA, HerbloreAction.SNAPDRAGON, HerbloreAction.CADANTINE,
            HerbloreAction.LANTADYME, HerbloreAction.DWARF_WEED, HerbloreAction.TORSTOL})
        { actions.put(action.name().replace("_LEAF", "").replace("RANARR_WEED", "RANARR").replace('_', ' '), action); }
        assertEquals(actions.size(), HerbloreEstimate.HERBS.size());
        for (HerbloreEstimate.Herb herb : HerbloreEstimate.HERBS)
        {
            HerbloreAction action = actions.get(herb.name.toUpperCase(java.util.Locale.ROOT));
            assertNotNull(herb.name, action);
            assertEquals(herb.name, Math.round(action.getXp() * 10), herb.cleaningTenths);
        }
    }
}

package com.farmingprofit;

import java.time.*;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;
import static org.junit.Assert.*;

public class HerbloreEstimateTest
{
    private final HerbloreEstimate.Choices defaults = new HerbloreEstimate.Choices(true, "");
    private FarmRun sample()
    {
        FarmRun run = new FarmRun(1);
        run.add(ItemID.UNIDENTIFIED_RANARR, "Grimy ranarr weed", 30, 5000, false, "Patch", "Harvest", 1);
        run.add(ItemID.UNIDENTIFIED_SNAPDRAGON, "Grimy snapdragon", 30, 6000, false, "Patch", "Sack harvest", 1);
        return run;
    }
    @Test public void multipleHerbsUseCorrectBaseXpAndCleaning()
    {
        HerbloreEstimate xp = new HerbloreEstimate(sample(), defaults);
        assertEquals(69000, xp.potionTenths); assertEquals(5790, xp.cleaningTenths);
        assertEquals(74790, xp.totalTenths()); assertEquals(60, xp.quantity);
    }
    @Test public void costsSecondariesAndOtherCropsNeverAddXp()
    {
        FarmRun run = sample();
        run.add(ItemID.UNIDENTIFIED_RANARR, "Ranarr cost", 10, 100, true, "Manual", "Cost", 2);
        run.add(ItemID.SNAPE_GRASS, "Snape grass", 100, 100, false, "Patch", "Harvest", 2);
        run.add(ItemID.DRAGONFRUIT, "Dragonfruit", 6, 100, false, "Tree", "Harvest", 2);
        run.add(ItemID.COINS, "GP adjustment", 100, 1, false, "Manual", "Correction", 2);
        assertEquals(74790, new HerbloreEstimate(run, defaults).totalTenths());
    }
    @Test public void correctionsSubtractAndZeroNetHerbsDisappear()
    {
        FarmRun run = sample();
        run.add(ItemID.UNIDENTIFIED_RANARR, "Ranarr", -30, 5000, false, "Manual", "Correct", 2);
        HerbloreEstimate xp = new HerbloreEstimate(run, defaults);
        assertEquals(1, xp.rows.size()); assertEquals(46290, xp.totalTenths());
        run.add(ItemID.UNIDENTIFIED_SNAPDRAGON, "Snapdragon", -31, 6000, false, "Manual", "Correct", 3);
        assertEquals(-1543, new HerbloreEstimate(run, defaults).totalTenths());
    }
    @Test public void recipesRecalculateExistingHistoryWithoutMutatingGp()
    {
        FarmRun run = sample().snapshot(); long profit = run.profit();
        HerbloreEstimate.Choices changed = new HerbloreEstimate.Choices(false,
            ItemID.UNIDENTIFIED_RANARR + ":" + ItemID._3DOSE1DEFENSE);
        assertEquals(65250, new HerbloreEstimate(run, changed).totalTenths());
        assertEquals(profit, run.profit()); assertEquals(2, run.entries.size());
        assertEquals(changed, new HerbloreEstimate.Choices(false, changed.encode()));
    }
    @Test public void invalidAndCrossHerbRecipeSettingsFallBackSafely()
    {
        HerbloreEstimate.Choices invalid = new HerbloreEstimate.Choices(true,
            "bad;123:456;" + ItemID.UNIDENTIFIED_RANARR + ":" + ItemID._3DOSE2RESTORE);
        assertEquals(defaults, invalid); assertEquals(defaults, new HerbloreEstimate.Choices(true, null));
    }
    @Test public void tenthsAccumulateWithoutRoundingEachHerb()
    {
        FarmRun run = new FarmRun(1);
        run.add(ItemID.UNIDENTIFIED_IRIT, "Irit", 3, 1, false, "Patch", "Harvest", 1);
        assertEquals(3264, new HerbloreEstimate(run, defaults).totalTenths());
    }
    @Test public void localCalendarPeriodsUseRunStartAndExcludeFutureDays()
    {
        ZoneId zone = ZoneId.of("America/New_York"); LocalDate today = LocalDate.of(2026, 11, 2);
        FarmRun sunday = new FarmRun(ZonedDateTime.of(2026, 11, 1, 23, 59, 0, 0, zone).toInstant().toEpochMilli());
        sunday.finishedAt = ZonedDateTime.of(2026, 11, 2, 0, 15, 0, 0, zone).toInstant().toEpochMilli();
        assertFalse(HerbloreEstimate.Period.TODAY.includes(sunday, today, zone));
        assertFalse(HerbloreEstimate.Period.WEEK.includes(sunday, today, zone));
        assertTrue(HerbloreEstimate.Period.MONTH.includes(sunday, today, zone));
        FarmRun monday = new FarmRun(today.atStartOfDay(zone).toInstant().toEpochMilli());
        assertTrue(HerbloreEstimate.Period.TODAY.includes(monday, today, zone));
        assertTrue(HerbloreEstimate.Period.WEEK.includes(monday, today, zone));
        FarmRun future = new FarmRun(today.plusDays(1).atStartOfDay(zone).toInstant().toEpochMilli());
        assertFalse(HerbloreEstimate.Period.MONTH.includes(future, today, zone));
        assertTrue(HerbloreEstimate.Period.ALL.includes(sunday, today, zone));
    }
}

package com.farmingprofit;

import java.awt.*;
import java.util.*;
import javax.swing.*;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;
import static org.junit.Assert.*;

public class HerblorePanelTest
{
    @Test public void changingRecipeAndCleaningRecalculatesRunAndHistory() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            FarmingProfitPlugin.Data data = new FarmingProfitPlugin.Data();
            FarmRun run = new FarmRun(System.currentTimeMillis());
            run.add(ItemID.UNIDENTIFIED_RANARR, "Grimy ranarr weed", 10, 5000, false, "Patch", "Harvest", 1);
            data.active = run; data.history.add(run.snapshot());
            Set<Integer> icons = new HashSet<>();
            FarmingProfitPanel panel = new FarmingProfitPanel(null, (label, id) -> icons.add(id));
            panel.render(data, "Saved locally", true); panel.selectXpView(true);
            assertTrue(labels(panel).contains("950 XP"));
            assertTrue(icons.contains(ItemID.UNIDENTIFIED_RANARR)); assertTrue(icons.contains(ItemID._3DOSEPRAYERRESTORE));
            panel.openRecipeEditor();
            JComboBox<?> ranarr = descendants(panel, JComboBox.class).stream()
                .filter(c -> "Ranarr potion choice".equals(c.getAccessibleContext().getAccessibleName())).findFirst().orElseThrow();
            ranarr.setSelectedIndex(1);
            descendants(panel, JCheckBox.class).get(0).setSelected(false);
            click(panel, "Done");
            assertTrue(labels(panel).contains("750 XP")); assertFalse(labels(panel).contains("950 XP"));
            assertTrue(icons.contains(ItemID._3DOSE1DEFENSE));
            assertEquals(50000, data.active.profit()); assertEquals(50000, data.history.get(0).profit());
            panel.selectXpView(false); assertTrue(labels(panel).contains("+50,000 gp"));
        });
    }
    @Test public void cancellingRecipeEditsDoesNotChangeEstimatesAndAccountSwitchClosesEditor() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            FarmingProfitPlugin.Data data = new FarmingProfitPlugin.Data();
            data.active = new FarmRun(1); data.active.add(ItemID.UNIDENTIFIED_RANARR, "Ranarr", 10, 1, false, "Patch", "Harvest", 1);
            FarmingProfitPanel panel = new FarmingProfitPanel(null);
            panel.render(data, "Saved locally", true, 1); panel.selectXpView(true); panel.openRecipeEditor();
            descendants(panel, JCheckBox.class).get(0).setSelected(false); click(panel, "Back");
            assertTrue(labels(panel).contains("950 XP"));
            panel.openRecipeEditor(); panel.render(new FarmingProfitPlugin.Data(), "Log in", false, 2);
            assertTrue(descendants(panel, PotionChoicesPanel.class).isEmpty());
            assertFalse(labels(panel).contains("950 XP"));
        });
    }
    @Test public void periodFiltersCompletedRunsAndNeverIncludesActiveRun() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            FarmingProfitPlugin.Data data = new FarmingProfitPlugin.Data();
            for (int days : new int[]{0, 1, 40})
            {
                FarmRun run = new FarmRun(java.time.LocalDate.now().minusDays(days).atStartOfDay(java.time.ZoneId.systemDefault()).toInstant().toEpochMilli());
                run.add(ItemID.UNIDENTIFIED_RANARR, "Ranarr", 10, 1, false, "Patch", "Harvest", run.startedAt);
                data.history.add(run);
            }
            data.active = new FarmRun(System.currentTimeMillis());
            data.active.add(ItemID.UNIDENTIFIED_RANARR, "Ranarr", 100, 1, false, "Patch", "Harvest", 1);
            FarmingProfitPanel panel = new FarmingProfitPanel(null); panel.render(data, "Saved locally", true); panel.selectXpView(true);
            assertEquals(3, runButtons(panel)); click(panel, "Today"); assertEquals(1, runButtons(panel));
            assertTrue(labels(panel).contains("950 XP")); click(panel, "All"); assertEquals(3, runButtons(panel));
            assertTrue(labels(panel).contains("2,850 XP"));
        });
    }
    @Test public void reopeningHistoryAfterMidnightRefreshesPeriod() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            java.util.concurrent.atomic.AtomicReference<java.time.LocalDate> day =
                new java.util.concurrent.atomic.AtomicReference<>(java.time.LocalDate.of(2026, 10, 30));
            FarmingProfitPlugin.Data data = new FarmingProfitPlugin.Data();
            FarmRun run = new FarmRun(day.get().atStartOfDay(java.time.ZoneId.systemDefault()).toInstant().toEpochMilli());
            run.add(ItemID.UNIDENTIFIED_RANARR, "Ranarr", 10, 1, false, "Patch", "Harvest", run.startedAt);
            data.history.add(run);
            FarmingProfitPanel panel = new FarmingProfitPanel(null, (label, id) -> {}, day::get);
            panel.render(data, "Saved locally", true); panel.selectXpView(true);
            JTabbedPane tabs = descendants(panel, JTabbedPane.class).get(0);
            tabs.setSelectedIndex(1); click(panel, "Today"); assertEquals(1, runButtons(panel));
            tabs.setSelectedIndex(0); day.set(day.get().plusDays(1)); tabs.setSelectedIndex(1);
            assertEquals(0, runButtons(panel)); click(panel, "All"); assertEquals(1, runButtons(panel));
            assertTrue(labels(panel).contains("Yesterday"));
        });
    }
    @Test public void routineFooterIsHiddenButSaveFailuresRemainVisible() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            FarmingProfitPlugin.Data data = new FarmingProfitPlugin.Data(); data.active = new FarmRun(1);
            FarmingProfitPanel panel = new FarmingProfitPanel(null); panel.render(data, "Saved locally | GE estimates", true);
            panel.selectXpView(true);
            assertFalse(descendants(panel, JLabel.class).stream().anyMatch(l -> l.isVisible() && l.getText() != null && l.getText().contains("Saved locally")));
            panel.render(data, "Save failed — recent changes are only in memory.", true);
            assertTrue(descendants(panel, JLabel.class).stream().anyMatch(l -> l.isVisible() && l.getText() != null && l.getText().contains("Save failed")));
        });
    }
    private static int runButtons(Container parent)
    { return (int) descendants(parent, JButton.class).stream().filter(b -> b.getAccessibleContext().getAccessibleName().startsWith("Open run ")).count(); }
    private static Set<String> labels(Container parent)
    {
        Set<String> labels = new HashSet<>(); descendants(parent, JLabel.class).forEach(l -> labels.add(l.getText())); return labels;
    }
    private static void click(Container parent, String label)
    { descendants(parent, JButton.class).stream().filter(b -> label.equals(b.getText())).findFirst().orElseThrow().doClick(0); }
    private static <T> java.util.List<T> descendants(Container parent, Class<T> type)
    {
        java.util.List<T> result = new ArrayList<>();
        for (Component child : parent.getComponents())
        {
            if (type.isInstance(child)) { result.add(type.cast(child)); }
            if (child instanceof Container) { result.addAll(descendants((Container) child, type)); }
        }
        return result;
    }
}

package com.farmingprofit;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.Reader;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;
import net.runelite.client.util.Filepath;
import static org.junit.Assert.*;

public class HistoryStoreTest
{
    @Rule public TemporaryFolder temporary = new TemporaryFolder();
    private final HistoryStore store = new HistoryStore(new Gson());
    private Filepath root() { return Filepath.Unchecked.getRooted(temporary.getRoot().toPath()); }
    private static FarmingProfitPlugin.Data data(int quantity)
    {
        FarmingProfitPlugin.Data data = new FarmingProfitPlugin.Data(); data.active = new FarmRun(1);
        data.active.add(1, "Crop", quantity, 100, false, "Patch", "Harvest", 2); return data;
    }

    @Test public void atomicWritesRoundTripAndAccountsRemainSeparate() throws Exception
    {
        store.save(root(), "profile-a", data(13).snapshot());
        store.save(root(), "profile-b", data(8).snapshot());
        assertEquals(1300, store.load(root(), "profile-a").active.profit());
        assertEquals(800, store.load(root(), "profile-b").active.profit());
        assertFalse(root().join("profile-a.pending").exists());
    }

    @Test public void deletedHistoryStaysDeletedWithoutChangingActiveOrOtherRuns() throws Exception
    {
        FarmingProfitPlugin.Data live = data(13);
        FarmRun removed = new FarmRun(10), kept = new FarmRun(20);
        live.history.add(removed); live.history.add(kept);
        FarmingProfitPlugin.Data before = live.snapshot();
        store.save(root(), "a", before);
        assertFalse(live.deleteHistory(1, 2, removed.id));
        assertFalse(live.deleteHistory(2, 2, live.active.id));
        assertEquals(2, live.history.size());
        assertTrue(live.deleteHistory(2, 2, removed.id));
        assertFalse(live.deleteHistory(2, 2, removed.id));
        assertEquals(2, before.history.size());
        assertEquals(1, live.snapshot().history.size());
        store.save(root(), "a", live.snapshot());
        FarmingProfitPlugin.Data restored = store.load(root(), "a");
        assertEquals(1300, restored.active.profit());
        assertEquals(1, restored.history.size());
        assertEquals(kept.id, restored.history.get(0).id);
        assertTrue(restored.deleteHistory(2, 2, kept.id));
        store.save(root(), "a", restored.snapshot());
        assertTrue(store.load(root(), "a").history.isEmpty());
    }

    @Test public void backupRetainsSessionStartAndRotatesAfterNextLoad() throws Exception
    {
        store.save(root(), "a", data(1).snapshot());
        store.load(root(), "a");
        store.save(root(), "a", data(2).snapshot());
        store.save(root(), "a", data(3).snapshot());
        assertEquals(100, readBackup().active.profit());
        store.load(root(), "a"); store.save(root(), "a", data(4).snapshot());
        assertEquals(300, readBackup().active.profit());
    }

    private FarmingProfitPlugin.Data readBackup() throws Exception
    {
        try (Reader reader = root().join("a.backup").openBufferedReader())
        { return new Gson().fromJson(reader, FarmingProfitPlugin.Data.class); }
    }

    @Test public void interruptedPendingWriteDoesNotReplacePrimary() throws Exception
    {
        store.save(root(), "a", data(13).snapshot());
        root().join("a.pending").write("{interrupted");
        assertEquals(1300, store.load(root(), "a").active.profit());
        store.save(root(), "a", data(14).snapshot());
        assertEquals(1400, store.load(root(), "a").active.profit());
    }

    @Test public void failedWritePreservesPrimaryAndNextSaveCanRecover() throws Exception
    {
        store.save(root(), "a", data(13).snapshot());
        root().join("a.pending").createDirectory(); // deterministic write failure, even as root
        assertThrows(IOException.class, () -> store.save(root(), "a", data(14).snapshot()));
        assertEquals(1300, store.load(root(), "a").active.profit());
        root().join("a.pending").deleteIfExists();
        store.save(root(), "a", data(14).snapshot());
        assertEquals(1400, store.load(root(), "a").active.profit());
    }

    @Test public void corruptPrimaryIsNeverOverwrittenOrCopiedOverBackup() throws Exception
    {
        store.save(root(), "a", data(1).snapshot()); store.save(root(), "a", data(2).snapshot());
        root().join("a.json").write("{broken");
        assertThrows(IOException.class, () -> store.load(root(), "a"));
        assertThrows(IOException.class, () -> store.save(root(), "a", data(3).snapshot()));
        assertEquals(100, readBackup().active.profit());
    }

    @Test public void missingPrimaryWithRecoveryDataDoesNotStartBlankHistory() throws Exception
    {
        root().join("a.pending").write(new Gson().toJson(data(13)));
        assertThrows(IOException.class, () -> store.load(root(), "a"));
        assertTrue(root().join("a.pending").exists());
    }

    @Test public void invalidSchemaAndNullWarningsAreRejected() throws Exception
    {
        for (String json : new String[]{"null", "{}", "{\"version\":2,\"history\":[]}", "{\"version\":1,\"history\":null}", "[]"})
        {
            root().join("a.json").write(json);
            assertThrows(IOException.class, () -> store.load(root(), "a"));
        }
        FarmingProfitPlugin.Data invalid = data(1); invalid.active.warnings.add(null);
        root().join("a.json").write(new Gson().toJson(invalid));
        assertThrows(IOException.class, () -> store.load(root(), "a"));
    }

    @Test public void unsafeProfileNamesCannotEscapeDirectory()
    {
        assertThrows(IllegalArgumentException.class, () -> store.load(root(), "../a"));
        assertThrows(IllegalArgumentException.class, () -> store.save(root(), "/tmp/a", data(1)));
    }
}

